glsl3.vert:
precision highp float;
uniform CCGlobal {
  mat4 cc_matView;
  mat4 cc_matViewInv;
  mat4 cc_matProj;
  mat4 cc_matProjInv;
  mat4 cc_matViewProj;
  mat4 cc_matViewProjInv;
  vec4 cc_cameraPos;
  vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_screenScale;
};
uniform CCLocal {
  mat4 cc_matWorld;
  mat4 cc_matWorldIT;
};
in vec3 a_position;
in vec4 a_color;
out vec4 v_color;
in vec2 a_uv0;
out vec2 v_uv0;
void main () {
  vec4 pos = vec4(a_position, 1);
  #if CC_USE_MODEL
  pos = cc_matViewProj * cc_matWorld * pos;
  #else
  pos = cc_matViewProj * pos;
  #endif
  v_uv0 = a_uv0;
  v_color = a_color;
  gl_Position = pos;
}

glsl3.frag:
precision highp float;
in vec4 v_color;
in vec2 v_uv0;
uniform sampler2D texture;
uniform Tear {
  vec4 tearParams;
  vec4 uvRect;
};
float hash11(float n) {
  return fract(sin(n) * 43758.5453123);
}
float hash21(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123);
}
float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  float a = hash21(i);
  float b = hash21(i + vec2(1.0, 0.0));
  float c = hash21(i + vec2(0.0, 1.0));
  float d = hash21(i + vec2(1.0, 1.0));
  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}
void main () {
  float progress = clamp(tearParams.x, 0.0, 1.0);
  float seed = tearParams.y;
  vec2 uvMin = uvRect.xy;
  vec2 uvSize = max(uvRect.zw, vec2(0.0001));
  vec2 uv = (v_uv0 - uvMin) / uvSize;
  float strips = 7.0;
  float warp = (noise(vec2(uv.y * 13.0, seed * 4.7)) - 0.5) * 0.18;
  float sx = uv.x * strips + warp;
  float sid = floor(sx);
  float f = fract(sx);
  float rnd = hash11(sid * 13.17 + seed * 9.1);
  float delay = rnd * 0.22;
  float local = clamp((progress - delay) / 0.78, 0.0, 1.0);
  local = local * local * (3.0 - 2.0 * local);
  vec2 sampleL = uv;
  sampleL.y -= local * (0.22 + rnd * 0.85);
  sampleL.x += (rnd - 0.5) * local * 0.55;
  sampleL.x += (uv.y - 0.5) * local * (rnd - 0.5) * 1.25;
  float crack = local * (0.035 + rnd * 0.04);
  float jag = (noise(vec2(uv.y * 32.0, sid + seed * 2.3)) - 0.5) * 0.1 * local;
  float edge = min(f, 1.0 - f);
  float lip = crack + jag;
  if (sampleL.x < 0.0 || sampleL.x > 1.0 || sampleL.y < 0.0 || sampleL.y > 1.0) {
    discard;
  }
  vec2 sampleUV = uvMin + sampleL * uvSize;
  vec4 o = texture2D(texture, sampleUV);
  o *= v_color;
  float flakes = noise(uv * vec2(16.0, 22.0) + vec2(seed * 3.1, sid));
  float holes = noise(uv * vec2(40.0, 9.0) - vec2(seed, rnd));
  if (flakes < progress * 0.72 - 0.08 || holes < progress * 0.45 - 0.2) {
    discard;
  }
  if (edge < lip) {
    if (edge < lip * 0.42) {
      discard;
    }
    vec3 paper = vec3(0.96, 0.92, 0.84);
    vec3 pencil = vec3(0.2, 0.16, 0.14);
    float fiber = noise(uv * vec2(78.0, 11.0) + sid);
    vec3 lipCol = mix(paper, pencil, smoothstep(0.42, 0.78, fiber) * 0.45);
    float mixLip = smoothstep(lip, lip * 0.42, edge);
    o.rgb = mix(o.rgb, lipCol, mixLip);
    o.a = max(o.a, mixLip);
  }
  o.a *= 1.0 - smoothstep(0.72, 1.0, progress);
  if (o.a < 0.02) {
    discard;
  }
  gl_FragColor = o;
}

